rt!(md.contains(\\\\\\\"**Error:** boom\\\\\\\"));\\\\n1087:         // Blank streaming placeholders never appear.\\\\n1088:         let mut empty = SessionRecord::new();\\\\n1089:         empty.messages.push(ChatMessage::assistant());\\\\n1090:         assert!(empty.to_markdown().contains(\\\\\\\"_No messages yet._\\\\\\\"));\\\\n1091:     }\\\\n1092: \\\\n1093:     /// Export writes `<slug>-<id8>.md` beside `sessions/` and re-exporting the\\\\n1094:     /// same session overwrites the same file.\\\\n1095:     #[test]\\\\n1096:     fn export_writes_markdown_next_to_sessions_and_overwrites() {\\\\n1097:         let dir = tmp_dir(\\\\\\\"export\\\\\\\");\\\\n1098:         let store = SessionStore::new(&dir);\\\\n1099: \\\\n1100:         let mut record = SessionRecord::new();\\\\n1101:         record.title = \\\\\\\"My Chat\\\\\\\".into();\\\\n1102:         record.messages.push(ChatMessage::user(\\\\\\\"hi\\\\\\\"));\\\\n1103:         store.save(&record).unwrap();\\\\n1104: \\\\n1105:         let path = store.export(&record).expect(\\\\\\\"export\\\\\\\");\\\\n1106:         assert_eq!(path.parent(), Some(store.export_dir().as_path()));\\\\n1107:         assert!(path\\\\n1108:             .file_name()\\\\n1109:             .unwrap()\\\\n1110:             .to_str()\\\\n1111:             .unwrap()\\\\n1112:             .starts_with(\\\\\\\"my-chat-\\\\\\\"));\\\\n1113:         let first = fs::read_to_string(&path).unwrap();\\\\n1114:         assert!(first.contains(\\\\\\\"# My Chat\\\\\\\"));\\\\n1115: \\\\n1116:         record.messages.push(ChatMessage::user(\\\\\\\"again\\\\\\\"));\\\\n1117:         let again = store.export(&record).unwrap();\\\\n1118:         assert_eq!(again, path);\\\\n1119:         let second = fs::read_to_string(&path).unwrap();\\\\n1120:         assert!(second.len() > first.len());\\\\n1121: \\\\n1122:         // load-by-id returns the saved record, None for unknown ids.\\\\n1123:         let loaded = store.load(&record.id).expect(\\\\\\\"load\\\\\\\");\\\\n1124:         assert_eq!(loaded.title, \\\\\\\"My Chat\\\\\\\");\\\\n1125:         assert!(store.load(\\\\\\\"missing-id\\\\\\\").is_none());\\\\n1126: \\\\n1127:         let _ = fs::remove_dir_all(&dir);\\\\n1128:     }\\\\n1129: \\\\n1130:     #[test]\\\\n1131:     fn fork_clones_the_prefix_into_a_fresh_record() {\\\\n1132:         let mut record = SessionRecord::new();\\\\n1133:         record.title = \\\\\\\"Base chat\\\\\\\".to_string();\\\\n1134:         record.messages.push(ChatMessage::user(\\\\\\\"q1\\\\\\\"));\\\\n1135:         record.messages.push(ChatMessage::assistant());\\\\n1136:         record.messages.push(ChatMessage::user(\\\\\\\"q2\\\\\\\"));\\\\n1137:         record.messages.push(ChatMessage::assistant());\\\\n1138:         record.plan.push(PlanItem {\\\\n1139:             text: \\\\\\\"step\\\\\\\".to_string(),\\\\n1140:             status: agent::tools::PlanStatus::Pending,\\\\n1141:         });\\\\n1142: \\\\n1143:         // Keeps messages[..index], carries the plan, new identity/title.\\\\n1144:         let fork = record.fork_from(2).expect(\\\\\\\"fork at index 2\\\\\\\");\\\\n1145:         assert_ne!(fork.id, record.id);\\\\n1146:         assert_eq!(fork.title, \\\\\\\"Base chat (branch)\\\\\\\");\\\\n1147:         assert_eq!(fork.messages.len(), 2);\\\\n1148:         assert_eq!(fork.messages[0].text, \\\\\\\"q1\\\\\\\");\\\\n1149:         assert_eq!(fork.plan.len(), 1);\\\\n1150:         assert!(record.messages.len() == 4, \\\\\\\"source must be untouched\\\\\\\");\\\\n1151: \\\\n1152:         // A pin is presentation *of that chat*, and a branch meant to be worked\\\\n1153:         // in must not inherit \\\\\\\"hidden\\\\\\\": both are reset, while the messages are\\\\n1154:         // what actually carries over.\\\\n1155:         record.pinned = true;\\\\n1156:         record.set_archived(true);\\\\n1157:         let branch = record\\\\n1158:             .fork_from(2)\\\\n1159:             .expect(\\\\\\\"fork of a pinned,