t reloaded = store.load(&record.id).expect(\\\\\\\"load\\\\\\\");\\\\n1196:         assert!(reloaded.pinned);\\\\n1197:         assert!(reloaded.archived_at.is_some());\\\\n1198:         assert!(\\\\n1199:             !reloaded.set_archived(false),\\\\n1200:             \\\\\\\"restoring clears the timestamp\\\\\\\"\\\\n1201:         );\\\\n1202:         assert!(reloaded.archived_at.is_none());\\\\n1203: \\\\n1204:         // A session file written before either field existed is live and\\\\n1205:         // unpinned, not a failed load: the sidebar would otherwise drop every\\\\n1206:         // chat that predates the pin.\\\\n1207:         let legacy = dir.join(\\\\\\\"legacy.json\\\\\\\");\\\\n1208:         fs::write(\\\\n1209:             &legacy,\\\\n1210:             r#\\\\\\\"{\\\\\\\"id\\\\\\\":\\\\\\\"legacy\\\\\\\",\\\\\\\"title\\\\\\\":\\\\\\\"old\\\\\\\",\\\\\\\"created_at\\\\\\\":1,\\\\\\\"updated_at\\\\\\\":2,\\\\\\\"messages\\\\\\\":[]}\\\\\\\"#,\\\\n1211:         )\\\\n1212:         .expect(\\\\\\\"write legacy\\\\\\\");\\\\n1213:         let loaded = store.load(\\\\\\\"legacy\\\\\\\").expect(\\\\\\\"legacy loads\\\\\\\");\\\\n1214:         assert!(!loaded.pinned && loaded.archived_at.is_none());\\\\n1215:         assert_eq!(loaded.title, \\\\\\\"old\\\\\\\");\\\\n1216:         let _ = fs::remove_dir_all(&dir);\\\\n1217:     }\\\\n1218: \\\\n1219:     #[test]\\\\n1220:     fn a_name_is_trimmed_capped_and_never_empty() {\\\\n1221:         let mut record = SessionRecord::new();\\\\n1222:         record.title = \\\\\\\"before\\\\\\\".to_string();\\\\n1223: \\\\n1224:         assert!(record.rename(\\\\\\\"   \\\\\\\").is_err());\\\\n1225:         assert_eq!(record.title, \\\\\\\"before\\\\\\\", \\\\\\\"a refused rename changes nothing\\\\\\\");\\\\n1226:         assert!(record.rename(&\\\\\\\"z\\\\\\\".repeat(81)).is_err());\\\\n1227:         assert_eq!(record.title, \\\\\\\"before\\\\\\\");\\\\n1228:         assert_eq!(\\\\n1229:             record.rename(\\\\\\\"  two words  \\\\\\\").expect(\\\\\\\"renamed\\\\\\\"),\\\\n1230:             \\\\\\\"two words\\\\\\\"\\\\n1231:         );\\\\n1232:         assert_eq!(record.title, \\\\\\\"two words\\\\\\\");\\\\n1233:     }\\\\n1234: \\\\n1235:     #[test]\\\\n1236:     fn deleting_a_session_moves_it_to_the_trash() {\\\\n1237:         let dir = tmp_dir(\\\\\\\"trash\\\\\\\");\\\\n1238:         let store = SessionStore::new(&dir);\\\\n1239:         let mut record = SessionRecord::new();\\\\n1240:         record.title = \\\\\\\"keep me maybe\\\\\\\".to_string();\\\\n1241:         store.save(&record).expect(\\\\\\\"saved\\\\\\\");\\\\n1242:         assert_eq!(store.load_all().len(), 1, \\\\\\\"the store starts with it\\\\\\\");\\\\n1243: \\\\n1244:         store.delete(&record.id);\\\\n1245:         assert!(store.load_all().is_empty(), \\\\\\\"it left the store\\\\\\\");\\\\n1246:         let trashed = store.trashed();\\\\n1247:         assert_eq!(trashed.len(), 1, \\\\\\\"but it is in the trash\\\\\\\");\\\\n1248:         assert_eq!(trashed[0].title, \\\\\\\"keep me maybe\\\\\\\", \\\\\\\"with its title intact\\\\\\\");\\\\n1249: \\\\n1250:         let title = store.restore(&record.id).expect(\\\\\\\"restore\\\\\\\");\\\\n1251:         assert_eq!(title, \\\\\\\"keep me maybe\\\\\\\");\\\\n1252:         assert!(store.trashed().is_empty(), \\\\\\\"the trash is empty again\\\\\\\");\\\\n1253:         assert_eq!(store.load_all().len(), 1, \\\\\\\"and it is back in the store\\\\\\\");\\\\n1254:     }\\\\n1255: \\\\n1256:     #[test]\\\\n1257:     fn trashed_sessions_stay_out_of_the_store_and_its_search() {\\\\n1258:         let dir = tmp_dir(\\\\\\\"trash-search\\\\\\\");\\\\n1259:         let store = SessionStore::new(&dir);\\\\n1260:         let mut record = SessionRecord::new();\\\\n1261:         record.messages.push(ChatMessage::user(\\\\\\\"findable phrase\\\\\\\"));\\\\n1262:         store.save(&record).expect(\\\\\\\"saved\\\\\\\");\\\\n1263:         store.search(\\\\