assert!(\\\\n5171:             set_session_pinned_in(&mut inner, &id, true)\\\\n5172:                 .expect(\\\\\\\"idempotent\\\\\\\")\\\\n5173:                 .pinned\\\\n5174:         );\\\\n5175:         assert_eq!(\\\\n5176:             record_mtime(&dir, &id),\\\\n5177:             pinned_at,\\\\n5178:             \\\\\\\"pinning an already-pinned chat rewrote the file\\\\\\\"\\\\n5179:         );\\\\n5180: \\\\n5181:         // Renaming and archiving are refused while the turn runs, so hiding a\\\\n5182:         // chat cannot hide the output it is producing.\\\\n5183:         assert!(rename_session_in(&mut inner, &id, \\\\\\\"later\\\\\\\").is_err());\\\\n5184:         assert!(set_session_archived_in(&mut inner, &id, true).is_err());\\\\n5185:         assert!(!reload(&inner, &id).archived_at.is_some());\\\\n5186:     }\\\\n5187: \\\\n5188:     #[test]\\\\n5189:     fn archiving_hides_a_chat_and_restoring_brings_it_back_whole() {\\\\n5190:         let mut inner = Inner::new();\\\\n5191:         inner.store = crate::session::SessionStore::new(private_store(\\\\\\\"archive\\\\\\\"));\\\\n5192:         let id = stored_chat(&mut inner, \\\\\\\"on the record\\\\\\\", \\\\\\\"the only prompt\\\\\\\");\\\\n5193:         let pinned = set_session_pinned_in(&mut inner, &id, true).expect(\\\\\\\"pinned\\\\\\\");\\\\n5194:         assert!(pinned.pinned);\\\\n5195: \\\\n5196:         let archived = set_session_archived_in(&mut inner, &id, true).expect(\\\\\\\"archived\\\\\\\");\\\\n5197:         assert!(\\\\n5198:             archived.archived && archived.pinned,\\\\n5199:             \\\\\\\"a pin survives archiving\\\\\\\"\\\\n5200:         );\\\\n5201:         let on_disk = reload(&inner, &id);\\\\n5202:         assert!(on_disk.archived_at.is_some());\\\\n5203:         assert_eq!(on_disk.messages.len(), 1, \\\\\\\"archiving destroys nothing\\\\\\\");\\\\n5204: \\\\n5205:         let back = set_session_archived_in(&mut inner, &id, false).expect(\\\\\\\"restored\\\\\\